function miscellaneous(title, f) {
  return [
    willThrow(title, "if size < 0 throw", () => f(Seq.range(1, 9), -1)),
    willThrow(title, "if size = 0 throw", () => f(Seq.range(1, 9), 0)),
    valueEqual(title, "millions - take 10", () => Option.isSome(Seq.last(Seq.take(f(Seq.range(1, 1000), 1000), 10))), true),
    valueEqual(title, "infinite - take 0", () => Seq.last(Seq.take(f(Seq.foreverWith(() => 1), 1000), 0)), undefined),
    valueEqual(title, "infinite - take 1", () => Option.isSome(Seq.last(Seq.take(f(Seq.foreverWith(() => 1), 1000), 4))), true),
    valueEqual(title, "totally lazy", () => Seq.last(Seq.take(f(Seq.replicateWith(throwIfInvoked, 3), 1000), 0)), undefined)
  ];
}

