function test$2(source, count, result) {
  return valueEqual("dropLast", "[" + source + "] " + count.toString() + " => [" + result + "]", () => Seq.join(Seq.dropLast(Seq.fromArray(undefined, undefined, source.split("")), count), ""), result);
}

let dropLastTests = [
  test$2("", 1, ""),
  test$2("", 99, ""),
  test$2("a", 1, ""),
  test$2("a", 99, ""),
  test$2("ab", 1, "a"),
  test$2("ab", 2, ""),
  test$2("ab", 99, ""),
  test$2("abc", 1, "ab"),
  test$2("abc", 2, "a"),
  test$2("abc", 3, ""),
  test$2("abc", 99, ""),
  test$2("abcdefg", 1, "abcdef")
].concat([
  willNotThrow("dropLast", "lazy", () => Seq.dropLast(Seq.onceWith(throwIfInvoked), 10)),
  willThrow("dropLast", "when count < 0, throw", () => Seq.dropLast(Seq.range(1, 5), -1)),
  valueEqual("dropLast", "when count = 0 return same instance", () => {
    let source = Seq.range(1, 5);
    let result = Seq.dropLast(source, 0);
    return source === result;
  }, true)
]);

